package com.fream.back.visible.t05;

import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationEvent;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.PayloadApplicationEvent;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.context.event.EventListener;
import org.springframework.core.type.filter.AnnotationTypeFilter;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionalEventListener;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * 테스트용 객체 조립기.
 *
 * - 리포지토리·EntityManager 등 테스트 컨텍스트(@DataJpaTest)에 있는 빈은 그대로 쓴다.
 * - com.fream.back.domain 아래의 @Service/@Component 클래스는 실제 객체로 생성자 주입해 만든다.
 * - 그 밖의 의존(외부 연동·Redis·WebSocket 등)은 Mockito mock으로 채운다.
 * - ApplicationEventPublisher로 발행한 이벤트는 domain 아래 @EventListener/@TransactionalEventListener 메서드로 즉시 전달한다.
 */
final class Wiring {

    private static final String DOMAIN = "com.fream.back.domain";

    private final ApplicationContext ctx;
    private final Map<Class<?>, Object> instances = new HashMap<>();
    private final Set<Class<?>> building = new HashSet<>();
    private List<Class<?>> listenerClasses;

    Wiring(ApplicationContext ctx) {
        this.ctx = ctx;
        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
    }

    <T> Wiring with(Class<T> type, T instance) {
        instances.put(type, instance);
        return this;
    }

    @SuppressWarnings("unchecked")
    <T> T get(Class<T> type) {
        Object existing = instances.get(type);
        if (existing != null) {
            return (T) existing;
        }
        if (type == String.class) {
            return (T) "";
        }
        if (type.isPrimitive()) {
            return (T) defaultPrimitive(type);
        }
        Object bean = ctx.getBeanProvider(type).getIfUnique();
        if (bean != null) {
            return (T) bean;
        }
        Object created;
        if (isDomainComponent(type) && !building.contains(type)) {
            building.add(type);
            try {
                created = construct(type);
            } finally {
                building.remove(type);
            }
        } else {
            created = Mockito.mock(type);
        }
        instances.put(type, created);
        return (T) created;
    }

    private static boolean isDomainComponent(Class<?> t) {
        return t.getName().startsWith(DOMAIN + ".")
                && !t.isInterface()
                && !Modifier.isAbstract(t.getModifiers())
                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
    }

    private Object construct(Class<?> type) {
        try {
            Constructor<?> ctor = null;
            for (Constructor<?> c : type.getDeclaredConstructors()) {
                if (c.isAnnotationPresent(Autowired.class)) {
                    ctor = c;
                }
            }
            if (ctor == null) {
                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
                        .max(Comparator.comparingInt(Constructor::getParameterCount))
                        .orElseThrow();
            }
            Class<?>[] params = ctor.getParameterTypes();
            Object[] args = new Object[params.length];
            for (int i = 0; i < params.length; i++) {
                args[i] = get(params[i]);
            }
            ctor.setAccessible(true);
            Object obj = ctor.newInstance(args);
            instances.put(type, obj);
            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
                for (Field f : c.getDeclaredFields()) {
                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
                        f.setAccessible(true);
                        if (f.get(obj) == null) {
                            f.set(obj, get(f.getType()));
                        }
                    }
                }
            }
            return obj;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot build " + type.getName(), e);
        }
    }

    private void dispatch(Object event) {
        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
        for (Class<?> listenerType : listenerClasses()) {
            for (Method m : listenerType.getDeclaredMethods()) {
                boolean listener = m.isAnnotationPresent(EventListener.class)
                        || m.isAnnotationPresent(TransactionalEventListener.class);
                if (!listener || m.getParameterCount() != 1) {
                    continue;
                }
                Class<?> p = m.getParameterTypes()[0];
                Object arg = p.isInstance(payload) ? payload
                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
                if (arg == null) {
                    continue;
                }
                try {
                    m.setAccessible(true);
                    m.invoke(get(listenerType), arg);
                } catch (InvocationTargetException e) {
                    Throwable t = e.getTargetException();
                    if (t instanceof RuntimeException re) {
                        throw re;
                    }
                    throw new IllegalStateException(t);
                } catch (IllegalAccessException e) {
                    throw new IllegalStateException(e);
                }
            }
        }
    }

    private List<Class<?>> listenerClasses() {
        if (listenerClasses == null) {
            listenerClasses = new ArrayList<>();
            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
                try {
                    Class<?> c = Class.forName(bd.getBeanClassName());
                    for (Method m : c.getDeclaredMethods()) {
                        if (m.isAnnotationPresent(EventListener.class)
                                || m.isAnnotationPresent(TransactionalEventListener.class)) {
                            listenerClasses.add(c);
                            break;
                        }
                    }
                } catch (ClassNotFoundException | LinkageError ignored) {
                    // 로드할 수 없는 후보는 건너뛴다
                }
            });
        }
        return listenerClasses;
    }

    private static Object defaultPrimitive(Class<?> t) {
        if (t == boolean.class) return false;
        if (t == char.class) return '\0';
        if (t == byte.class) return (byte) 0;
        if (t == short.class) return (short) 0;
        if (t == int.class) return 0;
        if (t == long.class) return 0L;
        if (t == float.class) return 0f;
        return 0d;
    }
}
    private static final int TIMEOUT_MS = 30000; // 30초

    /**
     * 배송 상태 처리기 생성자
     *
     * @param browserManager Playwright 브라우저 관리자
     * @param notificationService 알림 서비스
     * @param orderService 주문 서비스
     */
    public ShipmentItemProcessor(
            PlaywrightBrowserManager browserManager,
            NotificationCommandService notificationService,
            OrderShipmentCommandService orderService
    ) {
        this.browserManager = browserManager;
        this.notificationService = notificationService;
        this.orderService = orderService;
    }

    /**
     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
     *
     * @param orderShipment 처리할 배송 정보
     * @return 업데이트된 배송 정보
     * @throws Exception 처리 중 오류 발생 시
     */
    @Override
    public OrderShipment process(OrderShipment orderShipment) throws Exception {
        String trackingNumber = orderShipment.getTrackingNumber();
        Long shipmentId = orderShipment.getId();

        if (trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
        }

        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
                shipmentId, trackingNumber, orderShipment.getStatus());

        Page page = null;
        try {
            // browserManager를 통해 페이지 생성
            page = browserManager.newPage();
            if (page == null) {
                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
            }

            // 타임아웃 설정
            page.setDefaultTimeout(TIMEOUT_MS);

            // 배송 추적 URL로 이동
            String url = TRACKING_URL_PREFIX + trackingNumber;
            log.debug("배송 조회 페이지로 이동: {}", url);
            page.navigate(url);

            // 배송 상태 테이블 로드 대기
            log.debug("배송 상태 테이블 로드 대기");
            page.waitForSelector(STATUS_SELECTOR);

            // 최종 HTML 가져오기
            String renderedHtml = page.content();
            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());

            // HTML 파싱하여 배송 상태 추출
            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
            ShipmentStatus newStatus = mapToShipmentStatus(statusText);

            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
                    shipmentId, statusText, newStatus);

            // 현재 상태와 동일한 경우 중복 처리 방지
            if (orderShipment.getStatus() == newStatus) {
                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                        shipmentId, newStatus);
                return orderShipment;
            }

            // 상태에 따른 처리
            if (newStatus == ShipmentStatus.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}, orderId={}",
                        shipmentId, orderShipment.getOrder().getId());

                // 배송 상태 업데이트
                orderShipment.updateStatus(ShipmentStatus.DELIVERED);

                // 주문 완료 처리 및 알림
                orderService.completeOrder(orderShipment.getOrder().getId());
                notificationService.notifyShipmentCompleted(orderShipment.getOrder());

            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
            }

            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
                    shipmentId, orderShipment.getStatus());

            return orderShipment;

        } catch (Exception e) {
            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
                    shipmentId, trackingNumber, e.getMessage(), e);

            // ShipmentException 타입이 아닌 경우 래핑
            if (!(e instanceof ShipmentException)) {
                throw new ShipmentException(
                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                        e
                );
            }
            throw e;
        } finally {
            // 페이지 리소스 해제
            if (page != null) {
                try {
                    page.close();
                    log.debug("페이지 리소스 해제 완료");
                } catch (Exception e) {
                    log.warn("페이지 닫기 실패: {}", e.getMessage());
                }
            }
        }
    }

    /**
     * HTML에서 배송 상태를 파싱합니다.
     *
     * @param html 파싱할 HTML 문자열
     * @param trackingNumber 로깅용 운송장 번호
     * @return 배송 상태 문자열
     * @throws ShipmentException 파싱 실패 시 발생
     */
    private String parseStatusFromHtml(String html, String trackingNumber) {
        try {
            Document doc = Jsoup.parse(html);
            Elements rows = doc.select(STATUS_SELECTOR);

            if (rows.isEmpty()) {
                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
                throw new ShipmentException(
                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
                );
            }

            // 마지막 행(최신 상태)의 5번째 컬럼 선택
            String statusText = rows.last().select("td").get(4).text().trim();

            if (statusText.isEmpty()) {
                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
                throw new ShipmentException(
                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                        "배송 상태 정보를 찾을 수 없습니다."
                );
            }

            return statusText;

        } catch (IndexOutOfBoundsException e) {
            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
            throw new ShipmentException(
                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
                    e
            );
        } catch (Exception e) {

tool_use_result.stdout:
        return switch (statusText) {
            case "배송완료" -> ShipmentStatus.DELIVERED;
            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
            default -> ShipmentStatus.IN_TRANSIT;
        };
    }

    /**
     * OrderBid와 SaleBid의 상태를 COMPLETED로 업데이트합니다.
     *
     * @param orderId 주문 ID
     */
    @Transactional
    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);

        try {
            // OrderBid 조회
            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));

            // 상태를 COMPLETED로 업데이트
            if (orderBid.getStatus() == com.fream.back.domain.order.entity.BidStatus.MATCHED) {
                log.debug("OrderBid 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
                orderBid.updateStatus(com.fream.back.domain.order.entity.BidStatus.COMPLETED);
            }

            // SaleBid 상태 업데이트
            SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
            if (saleBid != null && saleBid.getStatus() == BidStatus.MATCHED) {
                log.debug("SaleBid 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
                saleBid.updateStatus(BidStatus.COMPLETED);
            }

            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);

        } catch (Exception e) {
            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
            // 상태 변경 실패는 로그만 남기고 진행 (주요 로직에 영향 주지 않음)
        }
    }

    /**
     * 단일 송장에 대해 즉시 상태를 갱신하고, 최종 상태를 반환합니다.
     *
     * @param shipmentId 배송 ID
     * @param courier 택배사
     * @param trackingNumber 운송장 번호
     * @return 갱신된 배송 상태
     * @throws ShipmentException 배송 상태 조회 실패 시 발생
     */
    @Transactional
    public ShipmentStatus updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {
            // 1) 기존 Shipment 로드
            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new ShipmentException(
                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));

            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
                    shipment.getId(), shipment.getStatus());

            // 2) 송장 정보 업데이트 (택배사, 송장번호)
            shipment.updateTrackingInfo(courier, trackingNumber);
            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);

            // 3) CJ대한통운 조회로 현재 상태 확인
            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
            ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);

            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);

            // 4) 상태에 따른 처리
            if (newStatus == ShipmentStatus.DELIVERED) {
                log.info("배송 완료 처리: shipmentId={}", shipmentId);

                shipment.updateStatus(ShipmentStatus.DELIVERED);

                // 주문 완료 로직
                completeOrder(shipment.getOrder().getId());

            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
                log.info("배송 출발 처리: shipmentId={}", shipmentId);
                shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);

            } else {
                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
                shipment.updateStatus(ShipmentStatus.IN_TRANSIT);
            }

            // 5) 상태 반환
            log.info("송장 상태 확인 완료: shipmentId={}, finalStatus={}",
                    shipmentId, shipment.getStatus());
            return shipment.getStatus();

        } catch (ShipmentException e) {
            throw e;
        } catch (Exception e) {
            log.error("송장 상태 확인 중 오류 발생: shipmentId={}, error={}",
                    shipmentId, e.getMessage(), e);
            throw new ShipmentException(
                    ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
                    "배송 상태 조회 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }
